// ── NaN ──────────────────────────────────────────────────────────────────────────────────────

/// Every function returns exactly `math::NAN` for every kind of NaN input, and for the invalid
/// operations that make a NaN, on every platform (the hardware's own NaNs differ in sign).
#[test]
fn every_nan_result_is_the_one_nan() {
    let nans: Vec<f32> = [
        0x7fc0_0000u32,
        0xffc0_0000,
        0x7f80_0001,
        0xff80_0001,
        0x7fa0_0000,
        0x7fc1_2345,
        0xffc1_2345,
        0x7fff_ffff,
        0xffff_ffff,
    ]
    .iter()
    .map(|&b| f32::from_bits(b))
    .collect();
    let want = math::NAN.to_bits();
    for &(name, f) in UNARY.iter().chain(HELPERS) {
        for &x in &nans {
            assert_eq!(f(x).to_bits(), want, "{name}({:08x})", x.to_bits());
        }
    }
    for &x in &nans {
        for &y in &[2.0f32, 0.5, -1.0, f32::INFINITY] {
            assert_eq!(
                math::powf(x, y).to_bits(),
                want,
                "powf({:08x}, {y})",
                x.to_bits()
            );
            assert_eq!(
                math::powf(y, x).to_bits(),
                want,
                "powf({y}, {:08x})",
                x.to_bits()
            );
        }
        let (s, c) = math::sin_cos(x);
        assert_eq!((s.to_bits(), c.to_bits()), (want, want));
    }
    // Invalid operations.
    let inf = f32::INFINITY;
    for (what, v) in [
        ("ln(-1)", math::ln(-1.0)),
        ("ln(-inf)", math::ln(-inf)),
        ("ln_1p(-2)", math::ln_1p(-2.0)),
        ("sin(inf)", math::sin(inf)),
        ("cos(-inf)", math::cos(-inf)),
        ("powf(-2, 0.5)", math::powf(-2.0, 0.5)),
        ("silu(-inf)", math::silu(-inf)),
        ("gelu_tanh(-inf)", math::gelu_tanh(-inf)),
    ] {
        assert_eq!(v.to_bits(), want, "{what}");
    }
    // The slices agree.
    let mut xs = nans.clone();
    xs.push(-inf);
    for (name, slice) in SLICES {
        let mut v = xs.clone();
        slice(&mut v);
        let scalar = SLICE_SCALAR.iter().find(|(n, _)| n == name).unwrap().1;
        for (x, y) in xs.iter().zip(&v) {
            assert_eq!(
                y.to_bits(),
                scalar(*x).to_bits(),
                "{name}({:08x})",
                x.to_bits()
            );
        }
    }
}

/// The special values the helpers give, which are what today's call-site expressions give.
#[test]
fn helper_special_values() {
    let inf = f32::INFINITY;
    let cases: [(&str, f32, f32); 12] = [
        ("silu(+inf)", math::silu(inf), inf),
        ("silu(-0)", math::silu(-0.0), -0.0),
        ("sigmoid(+inf)", math::sigmoid(inf), 1.0),
        ("sigmoid(-inf)", math::sigmoid(-inf), 0.0),
        ("gelu_tanh(+inf)", math::gelu_tanh(inf), inf),
        ("gelu_tanh(-0)", math::gelu_tanh(-0.0), -0.0),
        ("gelu_tanh(-1e20)", math::gelu_tanh(-1e20), -0.0),
        ("softplus(+inf)", math::softplus(inf), inf),
        ("softplus(-inf)", math::softplus(-inf), 0.0),
        ("tanh(-0)", math::tanh(-0.0), -0.0),
        ("exp(-inf)", math::exp(-inf), 0.0),
        ("exp(+inf)", math::exp(inf), inf),
    ];
    for (what, got, want) in cases {
        assert_eq!(got.to_bits(), want.to_bits(), "{what}: got {got:e}");
    }
    // And they are what the expressions the call sites write give, with the platform functions,
    // wherever the result is not a NaN (whose bits the platform chooses).
    for x in [inf, -inf, 0.0, -0.0, 1e20, -1e20, 100.0, -100.0] {
        let silu = x / (1.0 + (-x).exp());
        let sigmoid = 1.0 / (1.0 + (-x).exp());
        let gelu = 0.5 * x * (1.0 + (0.797_884_6 * (x + 0.044715 * x * x * x)).tanh());
        for (name, got, want) in [
            ("silu", math::silu(x), silu),
            ("sigmoid", math::sigmoid(x), sigmoid),
            ("gelu_tanh", math::gelu_tanh(x), gelu),
        ] {
            if want.is_nan() {
                assert!(got.is_nan(), "{name}({x})");
            } else {
                assert_eq!(got.to_bits(), want.to_bits(), "{name}({x})");
            }
        }
    }
}

// ── slices ───────────────────────────────────────────────────────────────────────────────────

type Slice = fn(&mut [f32]);

/// Every in-place slice function, by the name of its scalar function, at the active tier.
const SLICES: &[(&str, Slice)] = &[
    ("exp", math::exp_slice),
    ("tanh", math::tanh_slice),
    ("sigmoid", math::sigmoid_slice),
    ("silu", math::silu_slice),
    ("gelu_tanh", math::gelu_tanh_slice),
    ("exp_sub", exp_sub_3),
    ("exp_to", exp_to_copy),
];

/// `exp_sub_slice` with a fixed subtrahend, as an in-place `Slice`.
fn exp_sub_3(xs: &mut [f32]) {
    math::exp_sub_slice(xs, 3.0);
}

/// `exp_slice_to` through a copy, as an in-place `Slice`.
fn exp_to_copy(xs: &mut [f32]) {
    let src = xs.to_vec();
    math::exp_slice_to(&src, xs);
}

/// A slice function as a value: one tier's, or the active tier's.
type DynSlice = Box<dyn Fn(&mut [f32]) + Sync>;

/// The same functions as [`SLICES`], taken from one tier's table.
fn tier_slices(f: &'static math::SliceFns) -> Vec<(&'static str, DynSlice)> {
    vec![
        ("exp", Box::new(f.exp)),
        ("tanh", Box::new(f.tanh)),
        ("sigmoid", Box::new(f.sigmoid)),
        ("silu", Box::new(f.silu)),
        ("gelu_tanh", Box::new(f.gelu_tanh)),
        ("exp_sub", Box::new(|xs: &mut [f32]| (f.exp_sub)(xs, 3.0))),
        (
            "exp_to",
            Box::new(|xs: &mut [f32]| {
                let src = xs.to_vec();
                (f.exp_to)(&src, xs)
            }),
        ),
    ]
}

/// The tiers this CPU supports, found WITHOUT `math::Tier::supported` (the code under test), so
/// a tier the test skips is one the CPU really lacks.
fn host_tiers() -> Vec<math::Tier> {
    #[allow(unused_mut)]
    let mut v = vec![math::Tier::Baseline];
    #[cfg(target_arch = "x86_64")]
    {
        use std::arch::is_x86_feature_detected as has;
        if has!("avx2") {
            v.push(math::Tier::Avx2);
        }
        if has!("avx512f") && has!("avx512dq") && has!("avx512vl") && has!("avx512bw") {
            v.push(math::Tier::Avx512);
        }
    }
    v
}

/// Each tier's table for every tier this CPU has, asserting the module agrees on which those
/// are; prints the tiers it skips.
fn tiers_to_test() -> Vec<&'static math::SliceFns> {
    let host = host_tiers();
    let mut out = Vec::new();
    for t in math::Tier::ALL {
        match math::slice_fns(t) {
            Some(f) => {
                assert!(host.contains(&t), "{t:?} offered but the CPU lacks it");
                assert_eq!(f.tier, t, "{t:?}: table of the wrong tier");
                out.push(f);
            }
            None => {
                assert!(
                    !host.contains(&t),
                    "{t:?}: the CPU has it, the module refuses it"
                );
                println!("tier {}: SKIPPED, not supported by this CPU", t.name());
            }
        }
    }
    out
}

const SLICE_SCALAR: &[(&str, Unary)] = &[
    ("exp", math::exp),
    ("tanh", math::tanh),
    ("sigmoid", math::sigmoid),
    ("silu", math::silu),
    ("gelu_tanh", math::gelu_tanh),
    ("exp_sub", |x| math::exp(x - 3.0)),
    ("exp_to", math::exp),
];

/// Each slice function, at every tier this CPU supports and at the active tier, equals its
/// scalar function element for element on a dense grid, for awkward lengths and unaligned
/// starts (the vectorized loop's head, body and tail). It asserts it ran every tier the CPU
/// has, and prints the ones it skipped.
#[test]
fn slices_equal_scalars() {
    let mut xs = grid("silu");
    xs.extend(grid("exp"));
    let lens = [0usize, 1, 3, 7, 8, 9, 15, 16, 17, 31, 33, 63, 64, 65, 1000];
    let mut cases: Vec<(String, Vec<(&str, DynSlice)>)> = tiers_to_test()
        .into_iter()
        .map(|f| (f.tier.name().to_string(), tier_slices(f)))
        .collect();
    cases.push((
        "active".to_string(),
        SLICES
            .iter()
            .map(|&(n, s)| (n, Box::new(s) as DynSlice))
            .collect(),
    ));
    let mut ran = Vec::new();
    for (tier, slices) in &cases {
        for (name, slice) in slices {
            let scalar = SLICE_SCALAR.iter().find(|(n, _)| n == name).unwrap().1;
            // The whole grid in one call.
            let mut v = xs.clone();
            slice(&mut v);
            for (x, y) in xs.iter().zip(&v) {
                assert_eq!(
                    y.to_bits(),
                    scalar(*x).to_bits(),
                    "{tier} {name}({:08x})",
                    x.to_bits()
                );
            }
            // Short slices at every start offset 0..4 (alignment) into a buffer.
            for &n in &lens {
                for start in 0..4 {
                    let src = &xs[1000 + start..1000 + start + n];
                    let mut buf = vec![0f32; n + 4];
                    buf[start..start + n].copy_from_slice(src);
                    slice(&mut buf[start..start + n]);
                    for (x, y) in src.iter().zip(&buf[start..start + n]) {
                        assert_eq!(
                            y.to_bits(),
                            scalar(*x).to_bits(),
                            "{tier} {name} len {n} at {start}"
                        );
                    }
                }
            }
        }
        ran.push(tier.clone());
    }
    let want: Vec<String> = host_tiers()
        .iter()
        .map(|t| t.name().to_string())
        .chain(["active".to_string()])
        .collect();
    assert_eq!(ran, want, "tiers checked");
    println!("tiers checked: {ran:?}");
    // A mismatched destination is refused.
    let r = std::panic::catch_unwind(|| math::exp_slice_to(&[1.0, 2.0], &mut [0.0]));
    assert!(r.is_err());
}

/// The tier switch: names round-trip, and under each `kernels.cpu.max_tier` ceiling the slice
/// functions run the narrower of the ceiling's tier and the CPU's widest. (Process-wide: the
/// other tests take each tier's table directly and do not depend on which tier is active.)
#[test]
fn tier_switch() {
    use infr_core::simd::{self, SimdTier};
    for t in math::Tier::ALL {
        assert_eq!(math::Tier::parse(t.name()), Some(t));
        assert_eq!(math::Tier::parse(&t.name().to_uppercase()), Some(t));
    }
    assert_eq!(math::Tier::parse("sse9"), None);
    let host = host_tiers();
    assert_eq!(math::Tier::best(), *host.last().unwrap());
    for t in SimdTier::ALL {
        simd::set_max(Some(t));
        let want = if t.supported() { t } else { SimdTier::best() };
        assert_eq!(simd::active(), want, "{t:?}");
        assert_eq!(math::tier(), want.math(), "{t:?}");
        assert!(host.contains(&math::tier()));
    }
    simd::set_max(None);
    assert_eq!(math::tier(), math::Tier::best());
}

/// Each slice function equals its scalar function on every binary32 input, in batches, at
/// every tier this CPU supports.
#[test]
#[ignore = "exhaustive: all 2^32 inputs per slice function and tier; run in release"]
fn exhaustive_slices_equal_scalars() {
    let mut ran = Vec::new();
    for f in tiers_to_test() {
        for (name, slice) in tier_slices(f) {
            let scalar = SLICE_SCALAR.iter().find(|(n, _)| *n == name).unwrap().1;
            let slice = &slice;
            let t0 = Instant::now();
            let threads = std::thread::available_parallelism().map_or(4, |n| n.get()) as u64;
            let chunk = (1u64 << 32).div_ceil(threads);
            let bad: u64 = std::thread::scope(|s| {
                let hs: Vec<_> = (0..threads)
                    .map(|t| {
                        s.spawn(move || {
                            const BATCH: u64 = 1 << 16;
                            let mut buf = vec![0f32; BATCH as usize];
                            let mut bad = 0u64;
                            let end = ((t + 1) * chunk).min(1 << 32);
                            let mut b = t * chunk;
                            while b < end {
                                let n = BATCH.min(end - b) as usize;
                                for (i, v) in buf[..n].iter_mut().enumerate() {
                                    *v = f32::from_bits((b + i as u64) as u32);
                                }
                                slice(&mut buf[..n]);
                                for (i, y) in buf[..n].iter().enumerate() {
                                    let x = f32::from_bits((b + i as u64) as u32);
                                    bad += (y.to_bits() != scalar(x).to_bits()) as u64;
                                }
                                b += n as u64;
                            }
                            bad
                        })
                    })
                    .collect();
                hs.into_iter().map(|h| h.join().unwrap()).sum()
            });
            println!(
                "{} {name}_slice: {bad} of 2^32 inputs differ from the scalar function, {:.1} s",
                f.tier.name(),
                t0.elapsed().as_secs_f64()
            );
            assert_eq!(bad, 0, "{} {name}", f.tier.name());
        }
        ran.push(f.tier);
    }
    assert_eq!(ran, host_tiers(), "tiers checked");
}

// ── speed, for information ───────────────────────────────────────────────────────────────────

/// Median ns per call of each function against the platform's, single thread, interleaved
/// rounds over realistic inputs. Information for docs/math.md.
#[test]
#[ignore = "benchmark: run in release on a quiet machine"]
fn bench_against_std() {
    const N: usize = 1 << 16;
    const ROUNDS: usize = 15;
    let lin = |lo: f32, hi: f32| -> Vec<f32> {
        (0..N)
            .map(|i| lo + (hi - lo) * (i as f32 / N as f32))
            .collect()
    };
    let rope: Vec<f32> = (0..N)
        .map(|i| (i / 64) as f32 * 1_000_000f32.powf(-2.0 * (i % 64) as f32 / 128.0))
        .collect();
    let cases: Vec<(&str, Vec<f32>, Unary, Unary)> = vec![
        (
            "exp (softmax, -20..0)",
            lin(-20.0, 0.0),
            math::exp,
            f32::exp,
        ),
        ("ln (1e-6..4)", lin(1e-6, 4.0), math::ln, f32::ln),
        ("ln_1p (-0.9..4)", lin(-0.9, 4.0), math::ln_1p, f32::ln_1p),
        ("tanh (-6..6)", lin(-6.0, 6.0), math::tanh, f32::tanh),
        ("sin (RoPE)", rope.clone(), math::sin, f32::sin),
        ("cos (RoPE)", rope.clone(), math::cos, f32::cos),
        ("silu (-6..6)", lin(-6.0, 6.0), math::silu, |x| {
            x / (1.0 + (-x).exp())
        }),
    ];
    let time = |xs: &[f32], f: Unary| -> f64 {
        let t = Instant::now();
        let mut acc = 0u32;
        for &x in xs {
            acc ^= std::hint::black_box(f(std::hint::black_box(x))).to_bits();
        }
        std::hint::black_box(acc);
        t.elapsed().as_nanos() as f64 / xs.len() as f64
    };
    let median = |mut v: Vec<f64>| {
        v.sort_by(f64::total_cmp);
        v[v.len() / 2]
    };
    println!(
        "{:<24} {:>10} {:>10} {:>7}",
        "function", "math ns", "std ns", "ratio"
    );
    for (name, xs, ours, theirs) in &cases {
        let (mut a, mut b) = (Vec::new(), Vec::new());
        for _ in 0..ROUNDS {
            a.push(time(xs, *ours));
            b.push(time(xs, *theirs));
        }
        let (a, b) = (median(a), median(b));
        println!("{name:<24} {a:>10.2} {b:>10.2} {:>7.2}", a / b);
    }
    // Slices, per element, at every tier this CPU has, against a plain loop of the platform's
    // scalar function writing the same expression (which is what the call sites did before).
    type Pick = fn(&'static math::SliceFns) -> DynSlice;
    let slice_cases: Vec<(&str, Vec<f32>, Pick, Slice)> = vec![
        (
            "exp_slice",
            lin(-20.0, 0.0),
            |f| Box::new(f.exp),
            |v| v.iter_mut().for_each(|x| *x = x.exp()),
        ),
        (
            "exp_sub_slice",
            lin(-10.0, 10.0),
            |f| Box::new(move |v: &mut [f32]| (f.exp_sub)(v, 3.0)),
            |v| v.iter_mut().for_each(|x| *x = (*x - 3.0).exp()),
        ),
        (
            "tanh_slice",
            lin(-6.0, 6.0),
            |f| Box::new(f.tanh),
            |v| v.iter_mut().for_each(|x| *x = x.tanh()),
        ),
        (
            "sigmoid_slice",
            lin(-6.0, 6.0),
            |f| Box::new(f.sigmoid),
            |v| v.iter_mut().for_each(|x| *x = 1.0 / (1.0 + (-*x).exp())),
        ),
        (
            "silu_slice",
            lin(-6.0, 6.0),
            |f| Box::new(f.silu),
            |v| v.iter_mut().for_each(|x| *x = *x / (1.0 + (-*x).exp())),
        ),
        (
            "gelu_tanh_slice",
            lin(-6.0, 6.0),
            |f| Box::new(f.gelu_tanh),
            |v| {
                v.iter_mut().for_each(|x| {
                    let g = *x;
                    *x = 0.5 * g * (1.0 + (0.797_884_6 * (g + 0.044715 * g * g * g)).tanh())
                })
            },
        ),
    ];
    let time_slice = |xs: &[f32], f: &dyn Fn(&mut [f32])| -> f64 {
        let mut v = xs.to_vec();
        let t = Instant::now();
        f(std::hint::black_box(&mut v));
        std::hint::black_box(&v);
        t.elapsed().as_nanos() as f64 / xs.len() as f64
    };
    let tiers = tiers_to_test();
    print!("{:<24} {:>10}", "slice (ns per element)", "std");
    for f in &tiers {
        print!(" {:>10}", f.tier.name());
    }
    println!();
    for (name, xs, pick, theirs) in &slice_cases {
        let ours: Vec<DynSlice> = tiers.iter().map(|f| pick(f)).collect();
        let mut b = Vec::new();
        let mut a: Vec<Vec<f64>> = vec![Vec::new(); ours.len()];
        // Interleaved: each round times the platform loop and every tier once.
        for _ in 0..ROUNDS {
            b.push(time_slice(xs, theirs));
            for (o, t) in ours.iter().zip(&mut a) {
                t.push(time_slice(xs, o.as_ref()));
            }
        }
        print!("{name:<24} {:>10.2}", median(b));
        for t in a {
            print!(" {:>10.2}", median(t));
        }
        println!();
    }
    let pairs: Vec<(f32, f32)> = (0..N)
        .map(|i| (1_000_000.0f32, -2.0 * (i % 64) as f32 / 128.0))
        .collect();
    let (mut a, mut b) = (Vec::new(), Vec::new());
    for _ in 0..ROUNDS {
        let t = Instant::now();
        let mut acc = 0u32;
        for &(x, y) in &pairs {
            acc ^= std::hint::black_box(math::powf(std::hint::black_box(x), y)).to_bits();
        }
        std::hint::black_box(acc);
        a.push(t.elapsed().as_nanos() as f64 / N as f64);
        let t = Instant::now();
        for &(x, y) in &pairs {
            acc ^= std::hint::black_box(std::hint::black_box(x).powf(y)).to_bits();
        }
        std::hint::black_box(acc);
        b.push(t.elapsed().as_nanos() as f64 / N as f64);
    }
    let (a, b) = (median(a), median(b));
    println!(
        "{:<24} {a:>10.2} {b:>10.2} {:>7.2}",
        "powf (RoPE theta)",
        a / b
    );
}
